/* ----------------------------------------------------
   CSS Variables: 6 Distinct Neumorphic Themes
---------------------------------------------------- */
:root, [data-theme="classic"] {
    --bg-color: #e0e5ec;
    --surface-color: #e0e5ec;
    --text-main: #2d3748;
    --text-muted: #718096;
    --text-light: #a0aec0;
    --accent: #3b82f6;
    --accent-light: #60a5fa;
    --accent-glow: rgba(59, 130, 246, 0.25);
    --accent-gradient: linear-gradient(135deg, #3b82f6, #1d4ed8);
    --success: #10b981;
    --warning: #f59e0b;
    --danger: #ef4444;

    --shadow-outset-lg: 16px 16px 30px #a3b1c6, -16px -16px 30px #ffffff;
    --shadow-outset: 8px 8px 16px #a3b1c6, -8px -8px 16px #ffffff;
    --shadow-outset-sm: 4px 4px 8px #a3b1c6, -4px -4px 8px #ffffff;
    --shadow-inset: inset 5px 5px 10px #a3b1c6, inset -5px -5px 10px #ffffff;
    --shadow-inset-sm: inset 3px 3px 6px #a3b1c6, inset -3px -3px 6px #ffffff;
    --knob-gradient: linear-gradient(135deg, #f0f5fa, #cdd5e0);
