    background: var(--surface-color);
    box-shadow: var(--shadow-outset);
    border-radius: var(--card-radius);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.neu-card-sm {
    background: var(--surface-color);
    box-shadow: var(--shadow-outset-sm);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

