/* ----------------------------------------------------
   Fixed Version Switcher (Top-Right)
---------------------------------------------------- */
.version-switcher {
    position: fixed;
    top: 18px;
    right: 24px;
    z-index: 1000;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.5rem 0.75rem 0.5rem 1rem;
