/* ----------------------------------------------------
   Main App Layout Grid
---------------------------------------------------- */
.app-layout {
    display: grid;
    grid-template-columns: 280px 1fr;
    min-height: 100vh;
    gap: 0;
}

/* Sidebar Styles */
.sidebar {
    background: var(--surface-color);
    padding: 2rem 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 2rem;
    border-right: 1px solid rgba(0, 0, 0, 0.03);
    box-shadow: 4px 0 20px rgba(0, 0, 0, 0.02);
    z-index: 10;
}

.brand-header {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding-bottom: 0.5rem;
}

.brand-logo {
    width: 48px;
    height: 48px;
    border-radius: 14px;
    box-shadow: var(--shadow-outset);
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--surface-color);
    color: var(--accent);
}

.brand-logo svg {
    width: 26px;
    height: 26px;
    fill: currentColor;
}

.brand-text h1 {
    font-size: 1.15rem;

/* ----------------------------------------------------
   Main Content Workspace
---------------------------------------------------- */
.main-workspace {
    padding: 2rem 2.5rem;
    display: flex;
    flex-direction: column;
    gap: 2rem;
    max-width: 1400px;
    margin: 0 auto;
    width: 100%;
}

/* Top Header Navigation */
.top-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1.5rem;
    flex-wrap: wrap;
}

.search-container {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.2rem;
    border-radius: 16px;
    box-shadow: var(--shadow-inset);
    width: 340px;
    max-width: 100%;
}

.search-container svg {
    width: 18px;
    height: 18px;
    fill: var(--text-muted);
    flex-shrink: 0;
}

.search-container input {
    border: none;
    background: transparent;
    outline: none;
    color: var(--text-main);
    font-family: inherit;
    font-size: 0.9rem;
