/* ----------------------------------------------------
   KPI Metric Cards (Draggable Grid)
---------------------------------------------------- */
.kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
}

.kpi-card {
    padding: 1.5rem;
    position: relative;
    cursor: grab;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.kpi-card:active {
    cursor: grabbing;
    transform: scale(1.02);
    box-shadow: var(--shadow-outset-lg);
}

.kpi-card.dragging {
    opacity: 0.5;
    box-shadow: var(--shadow-inset);
}

.kpi-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.kpi-title {
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted);
}

.kpi-icon {
    width: 38px;
    height: 38px;
    border-radius: 12px;
    box-shadow: var(--shadow-outset-sm);
    display: flex;
    align-items: center

