    font-size: 1.1rem;
    font-weight: 800;
    color: var(--text-main);
}

.chart-title-wrap p {
    font-size: 0.8rem;
    color: var(--text-muted);
}

.chart-legend {
    display: flex;
    align-items: center;
    gap: 1.25rem;
}

.legend-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--text-muted);
}

.legend-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;

/* ----------------------------------------------------
   Kanban / Interactive Widgets Section
---------------------------------------------------- */
.bottom-widgets-grid {
    display: grid;
    grid-template-columns: 1.8fr 1.2fr;
    gap: 1.5rem;
}

.kanban-board {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    margin-top: 0.5rem;
}

.kanban-col {
    border-radius: 16px;
    padding: 1rem;
    box-shadow: var(--shadow-inset-sm);
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
    min-height: 220px;
}

.kanban-col-title {
    font-size: 0.78rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted);
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.kanban-task {
    padding: 0.85rem;
    border-radius: 12px;
    box-shadow: var(--shadow-outset-sm);
    background: var(--surface-color);
    cursor: grab;
